command:
tmp=$(mktemp -d); export PMW_HOME="$tmp/home"; export PMW_PROJECT_SLUG=bind-test; root="$PMW_HOME/projects/bind-test"; mkdir -p "$root/runs" "$root/briefs"; brief="$root/briefs/current.md"; printf '# 产品设计简报：测试
产品简报版本：v2
确认状态：已对齐

## 核心价值判断
- 一句话判断：已确认。
## 数据 / 能力 / 约束与不可虚构项
- 不可虚构项：不得虚构。
' > "$brief"; printf '{"current_run_id":"r1","latest_run_id":"r1","latest_brief":"%s","latest_brief_version":"v2"}
' "$brief" > "$root/project.json"; printf '{"ts":"2099-01-01T00:00:00Z","event":"gate","run_id":"r1","status":"已对齐","title":"产品简报确认","summary":"用户确认"}
{"ts":"2099-01-01T00:00:01Z","event":"decision","run_id":"r1","status":"已确认","title":"方案方向确认","summary":"默认方向已批准"}
' > "$root/runs/r1.jsonl"; printf '{"record_type":"item","run_id":"r1","scheme":"方案A","screen":"首屏","brief_path":"/tmp/old.md","brief_version":"v1","main_goal":"测试","anti_metric":"测试","non_fiction":"不得虚构","canvas_mode":"standard_first_screen","target_output_pixels":""}
' > "$root/prototype-board.jsonl"; bin/pmw-dashboard readiness --target prototype --details; rm -rf "$tmp"
